const resolveImg = (keyOrUrl) => IMG[keyOrUrl] ?? keyOrUrl;

const FLOAT_CSS = ``;

// Age counter: calendar difference computed in KST (UTC+9) from 2011-11-02 07:56.
const BIRTH_KST_MS = Date.UTC(2011, 10, 2, 7, 56) - 9 * 3600 * 1000;
const kstParts = (ms) => {
  const d = new Date(ms + 9 * 3600 * 1000);
  return { y: d.getUTCFullYear(), mo: d.getUTCMonth(), d: d.getUTCDate(), h: d.getUTCHours(), mi: d.getUTCMinutes(), s: d.getUTCSeconds(), ms: d.getUTCMilliseconds() };
};
const formatAge = (nowMs) => {
  const a = kstParts(BIRTH_KST_MS);
  const b = kstParts(Math.max(nowMs, BIRTH_KST_MS));
  let y = b.y - a.y, mo = b.mo - a.mo, d = b.d - a.d;
  // borrow from the day part when the birth time of day is later than the current time of day
  const birthTod = a.h * 3600 + a.mi * 60 + a.s;
  const nowTod = b.h * 3600 + b.mi * 60 + b.s;
  if (nowTod < birthTod) d -= 1;
  if (d < 0) { d += new Date(Date.UTC(b.y, b.mo, 0)).getUTCDate(); mo -= 1; }
  if (mo < 0) { mo += 12; y -= 1; }
  return `${y}Y ${mo}M ${d}D`;
};

function AgeCounter() {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 60000);
    return () => clearInterval(timer);
  }, []);
  return <span>Age: {formatAge(now)}</span>;
}

