// ===== Calculator 1.0 source (downloaded from the project card) =====
const CALC_PY_SOURCE = "import json\nimport math\nimport os\nimport random\nimport re\nfrom bisect import bisect_left, bisect_right\n\n# ─────────────────────────────────────────────────────────────\n#  수열 / 요세푸스 기능 (내장)\n# ─────────────────────────────────────────────────────────────\ndef LIS(a):\n    \"\"\"엄격 증가 부분수열 중 가장 긴 것의 길이.  LIS([3,1,2,5]) -> 3\"\"\"\n    tails = []\n    for x in a:\n        k = bisect_left(tails, x)\n        if k == len(tails):\n            tails.append(x)\n        else:\n            tails[k] = x\n    return len(tails)\n\n\ndef LISseq(a):\n    \"\"\"LIS 하나를 실제 수열로.  LISseq([3,1,2,5]) -> [1, 2, 5]\"\"\"\n    tails, tails_idx, prev = [], [], [-1] * len(a)\n    for i, x in enumerate(a):\n        k = bisect_left(tails, x)\n        if k == len(tails):\n            tails.append(x)\n            tails_idx.append(i)\n        else:\n            tails[k] = x\n            tails_idx[k] = i\n        prev[i] = tails_idx[k - 1] if k > 0 else -1\n    seq = []\n    i = tails_idx[-1] if tails_idx else -1\n    while i != -1:\n        seq.append(a[i])\n        i = prev[i]\n    return seq[::-1]\n\n\ndef LIScnt(a):\n    \"\"\"가장 긴 엄격 증가 부분수열의 '개수' (인덱스가 다르면 다른 것으로 셈).\n    LIScnt([1,3,5,4,7]) -> 2   (1,3,5,7 / 1,3,4,7)      O(n log n)\n    \"\"\"\n    tails = []          # tails[k] = 길이 k+1 증가수열의 가장 작은 끝값\n    neg = []            # neg[k]  = 레벨 k 원소값들의 부호 반전(비감소 순서)\n    pref = []           # pref[k] = 레벨 k 개수의 누적합 (맨 앞에 0)\n    for x in a:\n        k = bisect_left(tails, x)\n        if k == 0:\n            c = 1\n        else:\n            j = bisect_right(neg[k - 1], -x)      # 레벨 k-1 중 값 < x 인 것은 j번째부터\n            c = pref[k - 1][-1] - pref[k - 1][j]\n        if k == len(tails):\n            tails.append(x)\n            neg.append([])\n            pref.append([0])\n        else:\n            tails[k] = x\n        neg[k].append(-x)\n        pref[k].append(pref[k][-1] + c)\n    return pref[-1][-1] if pref else 0\n\n\ndef josephus(n, k):\n    \"\"\"요세푸스: n명이 원형, k번째마다 제거할 때 마지막 생존자 번호(1부터).\"\"\"\n    n, k = int(n), int(k)\n    if n < 1 or k < 1:\n        raise ValueError(\"n, k는 1 이상이어야 합니다\")\n    f = 0\n    for i in range(2, n + 1):\n        f = (f + k) % i\n    return f + 1\n\n\ndef josephus_seq(n, k):\n    \"\"\"요세푸스 순열: 제거되는 사람 번호를 순서대로.  josephus_seq(7,3) -> [3,6,2,7,5,1,4]\"\"\"\n    n, k = int(n), int(k)\n    if n < 1 or k < 1:\n        raise ValueError(\"n, k는 1 이상이어야 합니다\")\n    people = list(range(1, n + 1))\n    out, i = [], 0\n    while people:\n        i = (i + k - 1) % len(people)\n        out.append(people.pop(i))\n    return out\n\n\n# ─────────────────────────────────────────────────────────────\n#  계산 엔진 (화면과 분리)\n# ─────────────────────────────────────────────────────────────\nANGLE = {\"deg\": True}        # True: 도(degree), False: 라디안\n\n\ndef _to_rad(x):\n    return math.radians(x) if ANGLE[\"deg\"] else x\n\n\ndef _from_rad(x):\n    return math.degrees(x) if ANGLE[\"deg\"] else x\n\n\ndef _snap(v):\n    return 0.0 if abs(v) < 1e-15 else v\n\n\ndef sin(x):\n    return _snap(math.sin(_to_rad(x)))\n\n\ndef cos(x):\n    return _snap(math.cos(_to_rad(x)))\n\n\ndef tan(x):\n    c = cos(x)\n    if c == 0:\n        raise ValueError(\"tan 값이 정의되지 않습니다\")\n    return sin(x) / c\n\n\ndef asin(x):\n    return _from_rad(math.asin(x))\n\n\ndef acos(x):\n    return _from_rad(math.acos(x))\n\n\ndef atan(x):\n    return _from_rad(math.atan(x))\n\n\ndef cbrt(x):\n    if hasattr(math, \"cbrt\"):\n        return math.cbrt(x)\n    return math.copysign(abs(x) ** (1 / 3), x)\n\n\nNS = {k: getattr(math, k) for k in dir(math) if not k.startswith(\"_\")}\nNS.update({\n    \"__builtins__\": {},\n    \"sin\": sin, \"cos\": cos, \"tan\": tan,\n    \"asin\": asin, \"acos\": acos, \"atan\": atan, \"cbrt\": cbrt,\n    \"abs\": abs, \"round\": round, \"max\": max, \"min\": min, \"pow\": pow, \"sum\": sum,\n    \"int\": int, \"float\": float, \"random\": random,\n    \"LIS\": LIS, \"LISseq\": LISseq, \"LIScnt\": LIScnt,\n    \"josephus\": josephus, \"josephus_seq\": josephus_seq,\n})\n\n\ndef evaluate(expr):\n    expr = expr.strip()\n    if not expr:\n        raise ValueError(\"식이 비어 있습니다\")\n    expr = expr.replace(\"×\", \"*\").replace(\"÷\", \"/\").replace(\"^\", \"**\")\n    expr = re.sub(r\"(?<![\\w.])0+(?=\\d)\", \"\", expr)      # 007 → 7\n    return eval(expr, NS)\n\n\ndef fmt(v):\n    if isinstance(v, bool):\n        return str(v)\n    if isinstance(v, float):\n        if v != v or v in (math.inf, -math.inf):\n            return str(v)\n        if v.is_integer() and abs(v) < 1e15:\n            return str(int(v))\n        return f\"{v:.12g}\"\n    return str(v)\n\n\ndef error_text(e):\n    if isinstance(e, ZeroDivisionError):\n        return \"0으로 나눌 수 없습니다\"\n    if isinstance(e, SyntaxError):\n        return \"식 형식 오류 (괄호/연산자 확인)\"\n    if isinstance(e, NameError):\n        return f\"알 수 없는 이름: {getattr(e, 'name', '')}\"\n    if isinstance(e, TypeError):\n        return \"함수 인자 오류 (개수/종류 확인)\"\n    return f\"{type(e).__name__}: {e}\"\n\n\n# ─────────────────────────────────────────────────────────────\n#  색 옵션\n# ─────────────────────────────────────────────────────────────\nGROUP_NAMES = {\n    \"op\": \"연산자 (+ - × / = C)\",\n    \"num\": \"숫자 1~9\",\n    \"zero\": \"0 / 00 / 000 / . , ⌫ / DEG\",\n    \"trig\": \"삼각함수 · rad/deg\",\n    \"pow\": \"거듭제곱 · 로그 · 제곱근\",\n    \"misc\": \"기타 함수\",\n    \"paren\": \"괄호\",\n    \"seq\": \"LIS · 요세푸스\",\n}\n\nTHEMES = {\n    \"기본\": dict(op=\"black\", num=\"hotpink\", zero=\"springgreen\", trig=\"gold\", pow=\"royalblue\",\n               misc=\"violet\", paren=\"orange\", seq=\"silver\",\n               win=\"#f0f0f0\", log_bg=\"white\", log_fg=\"black\"),\n    # V4 리뉴얼 에디션: 같은 색 + 모든 버튼 글자 흰색(fg)\n    \"V4 리뉴얼\": dict(op=\"black\", num=\"hotpink\", zero=\"springgreen\", trig=\"gold\", pow=\"royalblue\",\n                  misc=\"royalblue\", paren=\"black\", seq=\"royalblue\",\n                  win=\"#f0f0f0\", log_bg=\"white\", log_fg=\"black\", fg=\"white\"),\n    # V4 원본: 색 없는 기본 회색 버튼\n    \"V4 원본\": dict(op=\"#e1e1e1\", num=\"#e1e1e1\", zero=\"#e1e1e1\", trig=\"#e1e1e1\", pow=\"#e1e1e1\",\n                misc=\"#e1e1e1\", paren=\"#e1e1e1\", seq=\"#e1e1e1\",\n                win=\"#f0f0f0\", log_bg=\"white\", log_fg=\"black\"),\n    \"다크\": dict(op=\"#2b2b2b\", num=\"#c2185b\", zero=\"#2e7d32\", trig=\"#b8860b\", pow=\"#1e4fa3\",\n               misc=\"#6a3d9a\", paren=\"#d2691e\", seq=\"#555555\",\n               win=\"#1e1e1e\", log_bg=\"#2a2a2a\", log_fg=\"#e8e8e8\"),\n    \"파스텔\": dict(op=\"#a8a8c8\", num=\"#ffb6c9\", zero=\"#b5ead7\", trig=\"#fff1a8\", pow=\"#b5d0ff\",\n                misc=\"#e0c3fc\", paren=\"#ffd8b1\", seq=\"#d9d9d9\",\n                win=\"#fffaf5\", log_bg=\"#ffffff\", log_fg=\"#333333\"),\n    \"흑백\": dict(op=\"#000000\", num=\"#555555\", zero=\"#888888\", trig=\"#aaaaaa\", pow=\"#777777\",\n               misc=\"#999999\", paren=\"#333333\", seq=\"#cccccc\",\n               win=\"#ffffff\", log_bg=\"#ffffff\", log_fg=\"#000000\"),\n    # 폴라리스: 하늘색 + 흰색\n    \"폴라리스\": dict(op=\"#0288d1\", num=\"#81d4fa\", zero=\"#ffffff\", trig=\"#b3e5fc\", pow=\"#29b6f6\",\n                  misc=\"#e1f5fe\", paren=\"#4fc3f7\", seq=\"#90caf9\",\n                  win=\"#e8f6fd\", log_bg=\"#ffffff\", log_fg=\"#01579b\"),\n    # 솔라리스: 갈색 · 적색 · 노랑 · 주황\n    \"솔라리스\": dict(op=\"#5d3a1a\", num=\"#c62828\", zero=\"#8d5524\", trig=\"#fbc02d\", pow=\"#ef6c00\",\n                  misc=\"#d84315\", paren=\"#a1521f\", seq=\"#f9a825\",\n                  win=\"#3e2723\", log_bg=\"#fff3e0\", log_fg=\"#3e2723\"),\n    # 미드나이트: 흑색 · 보라 · 분홍 + 흰색\n    \"미드나이트\": dict(op=\"#0a0a14\", num=\"#e91e8c\", zero=\"#4a148c\", trig=\"#7b1fa2\", pow=\"#311b92\",\n                   misc=\"#ba68c8\", paren=\"#d81b60\", seq=\"#1a1a2e\",\n                   win=\"#0d0b1a\", log_bg=\"#14102a\", log_fg=\"#ffffff\"),\n    \"바다\": dict(op=\"#003b5c\", num=\"#0077b6\", zero=\"#2a9d8f\", trig=\"#90e0ef\", pow=\"#023e8a\",\n               misc=\"#48cae4\", paren=\"#00b4d8\", seq=\"#adb5bd\",\n               win=\"#e6f4f8\", log_bg=\"#ffffff\", log_fg=\"#022b3a\"),\n}\n\n\n# ── 내 테마 저장/불러오기 (계산기 파일 옆의 calc_themes.json) ──\nBUILTIN_THEMES = set(THEMES)\nTHEME_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), \"calc_themes.json\")\nTHEME_KEYS = list(GROUP_NAMES) + [\"win\", \"log_bg\", \"log_fg\", \"fg\"]\n\n\ndef load_user_themes(path=THEME_FILE):\n    try:\n        with open(path, \"r\", encoding=\"utf-8\") as f:\n            data = json.load(f)\n    except (OSError, ValueError):\n        return\n    for name, th in data.items():\n        if name in BUILTIN_THEMES or not isinstance(th, dict):\n            continue\n        if all(g in th for g in GROUP_NAMES):                 # 필수 키가 다 있는 것만\n            THEMES[name] = {k: th[k] for k in THEME_KEYS if th.get(k)}\n            THEMES[name].setdefault(\"win\", \"#f0f0f0\")\n            THEMES[name].setdefault(\"log_bg\", \"white\")\n            THEMES[name].setdefault(\"log_fg\", \"black\")\n\n\ndef save_user_themes(path=THEME_FILE):\n    mine = {n: t for n, t in THEMES.items() if n not in BUILTIN_THEMES}\n    try:\n        with open(path, \"w\", encoding=\"utf-8\") as f:\n            json.dump(mine, f, ensure_ascii=False, indent=2)\n        return True\n    except OSError:\n        return False\n\n\ndef P(label, text, back, group):\n    return (label, \"put\", text, back, group)\n\n\nGRID = [\n    [(\"+\", \"put\", \"+\", 0, \"op\"), (\"-\", \"put\", \"-\", 0, \"op\"), (\"×\", \"put\", \"*\", 0, \"op\"),\n     P(\"(\", \"(\", 0, \"paren\"),\n     P(\"sin\", \"sin()\", 1, \"trig\"), P(\"asin\", \"asin()\", 1, \"trig\"),\n     P(\"^2\", \"**2\", 0, \"pow\"), P(\"^\", \"**\", 0, \"pow\"), P(\"log2\", \"log2()\", 1, \"pow\")],\n    [(\"/\", \"put\", \"/\", 0, \"op\"), (\"=\", \"eq\", \"\", 0, \"op\"), (\"C\", \"clear\", \"\", 0, \"op\"),\n     P(\")\", \")\", 0, \"paren\"),\n     P(\"cos\", \"cos()\", 1, \"trig\"), P(\"acos\", \"acos()\", 1, \"trig\"),\n     P(\"sqrt\", \"sqrt()\", 1, \"pow\"), P(\"cbrt\", \"cbrt()\", 1, \"pow\"), P(\"2^x\", \"2**\", 0, \"pow\")],\n    [P(\"1\", \"1\", 0, \"num\"), P(\"2\", \"2\", 0, \"num\"), P(\"3\", \"3\", 0, \"num\"),\n     P(\".\", \".\", 0, \"zero\"),\n     P(\"tan\", \"tan()\", 1, \"trig\"), P(\"atan\", \"atan()\", 1, \"trig\"),\n     P(\"10^x\", \"10**\", 0, \"pow\"), P(\"log10\", \"log10()\", 1, \"pow\"), P(\"isqrt\", \"isqrt()\", 1, \"pow\")],\n    [P(\"4\", \"4\", 0, \"num\"), P(\"5\", \"5\", 0, \"num\"), P(\"6\", \"6\", 0, \"num\"),\n     P(\",\", \",\", 0, \"zero\"),\n     P(\"rad\", \"radians()\", 1, \"trig\"), P(\"deg\", \"degrees()\", 1, \"trig\"),\n     P(\"LIS\", \"LIS([])\", 2, \"seq\"), P(\"LISseq\", \"LISseq([])\", 2, \"seq\"),\n     P(\"LIScnt\", \"LIScnt([])\", 2, \"seq\")],\n    [P(\"7\", \"7\", 0, \"num\"), P(\"8\", \"8\", 0, \"num\"), P(\"9\", \"9\", 0, \"num\"),\n     (\"⌫\", \"back\", \"\", 0, \"zero\"),\n     P(\"floor\", \"floor()\", 1, \"misc\"), P(\"GCD\", \"gcd()\", 1, \"misc\"),\n     P(\"round\", \"round()\", 1, \"misc\"), P(\"max\", \"max()\", 1, \"misc\"),\n     P(\"rand01\", \"random.random()\", 0, \"misc\")],\n    [P(\"0\", \"0\", 0, \"zero\"), P(\"00\", \"00\", 0, \"zero\"), P(\"000\", \"000\", 0, \"zero\"),\n     (\"DEG\", \"mode\", \"\", 0, \"zero\"),\n     P(\"e\", \"e\", 0, \"misc\"), P(\"pi\", \"pi\", 0, \"misc\"),\n     P(\"abs\", \"fabs()\", 1, \"misc\"), P(\"min\", \"min()\", 1, \"misc\"), P(\"mod\", \"fmod()\", 1, \"misc\")],\n    [P(\"요세푸스\\n(생존자)\", \"josephus()\", 1, \"seq\"), P(\"요세푸스\\n(순서)\", \"josephus_seq()\", 1, \"seq\"), None, None,\n     P(\"ceil\", \"ceil()\", 1, \"misc\"), P(\"LCM\", \"lcm()\", 1, \"misc\"),\n     P(\"!\", \"factorial()\", 1, \"misc\"), P(\"1/x\", \"1/()\", 1, \"misc\"),\n     P(\"random\", \"random.randint()\", 1, \"misc\")],\n]\n\n\ndef main():\n    import tkinter as tk\n    from tkinter import filedialog, colorchooser, simpledialog, messagebox\n\n    win = tk.Tk()\n    win.title(\"Calculator 1.0\")\n    win.geometry(\"900x500\")\n    win.resizable(False, False)\n\n    entry1 = tk.Entry(win, font=(\"Arial\", 15))\n    out_var = tk.StringVar()\n    entry2 = tk.Entry(win, font=(\"Arial\", 15, \"bold\"), textvariable=out_var,\n                      state=\"readonly\", readonlybackground=\"#f2f2f2\", justify=\"right\")\n    entry1.place(x=0, y=0, width=530, height=34)\n    entry2.place(x=0, y=38, width=530, height=34)\n    txt1 = tk.Text(win, font=(\"Consolas\", 11))\n    txt1.place(x=545, y=0, width=345, height=490)\n\n    def put(text, back=0):\n        entry1.insert(tk.INSERT, text)\n        if back:\n            entry1.icursor(entry1.index(tk.INSERT) - back)\n        entry1.focus_set()\n\n    def equal(event=None):\n        expr = entry1.get()\n        try:\n            res = fmt(evaluate(expr))\n        except Exception as e:\n            entry2.config(readonlybackground=\"#ffd6d6\")\n            out_var.set(\"오류: \" + error_text(e))\n            return\n        entry2.config(readonlybackground=\"#f2f2f2\")\n        out_var.set(res)\n        txt1.insert(tk.END, f\"{expr} = {res}\\n\")\n        txt1.see(tk.END)\n\n    def clear():\n        entry1.delete(0, tk.END)\n        out_var.set(\"\")\n        entry2.config(readonlybackground=\"#f2f2f2\")\n        entry1.focus_set()\n\n    def backspace():\n        pos = entry1.index(tk.INSERT)\n        if pos > 0:\n            entry1.delete(pos - 1)\n        entry1.focus_set()\n\n    buttons = []          # (버튼, 그룹)\n    mode_btn = {}\n\n    def toggle_mode():\n        ANGLE[\"deg\"] = not ANGLE[\"deg\"]\n        mode_btn[\"b\"].config(text=\"DEG\" if ANGLE[\"deg\"] else \"RAD\")\n        entry1.focus_set()\n\n    # ── 색 적용 ──\n    colors = dict(THEMES[\"기본\"])\n\n    def text_color_for(bg):\n        r, g, b = win.winfo_rgb(bg)\n        lum = (0.299 * r + 0.587 * g + 0.114 * b) / 65535\n        return \"black\" if lum > 0.6 else \"white\"\n\n    def apply_colors():\n        for btn, group in buttons:\n            bg = colors[group]\n            fg = colors.get(\"fg\") or text_color_for(bg)\n            btn.config(bg=bg, fg=fg, activebackground=bg)\n        win.config(bg=colors[\"win\"])\n        txt1.config(bg=colors[\"log_bg\"], fg=colors[\"log_fg\"], insertbackground=colors[\"log_fg\"])\n\n    def set_theme(name):\n        colors.update(THEMES[name])\n        colors[\"fg\"] = THEMES[name].get(\"fg\")      # 글자색 고정 테마가 아니면 자동\n        apply_colors()\n\n    def pick_group(group):\n        res = colorchooser.askcolor(color=colors[group], parent=win,\n                                    title=GROUP_NAMES[group])\n        if res and res[1]:\n            colors[group] = res[1]\n            colors[\"fg\"] = None                    # 직접 고른 뒤엔 글자색 자동\n            apply_colors()\n\n    def pick_extra(key, title):\n        res = colorchooser.askcolor(color=colors[key], parent=win, title=title)\n        if res and res[1]:\n            colors[key] = res[1]\n            apply_colors()\n\n    # ── 버튼 생성 ──\n    for r, row in enumerate(GRID):\n        for c, cell in enumerate(row):\n            if cell is None:\n                continue\n            label, act, text, back, group = cell\n            if act == \"put\":\n                cmd = lambda t=text, b=back: put(t, b)\n            else:\n                cmd = {\"eq\": equal, \"clear\": clear, \"back\": backspace, \"mode\": toggle_mode}[act]\n            btn = tk.Button(win, text=label, command=cmd)\n            btn.place(x=c * 60, y=80 + r * 60, width=50, height=50)\n            buttons.append((btn, group))\n            if act == \"mode\":\n                mode_btn[\"b\"] = btn\n\n    win.bind(\"<Return>\", equal)\n\n    # ── 메뉴 ──\n    def open_file():\n        path = filedialog.askopenfilename(parent=win)\n        if path:\n            with open(path, \"r\", encoding=\"utf-8\", errors=\"replace\") as f:\n                data = f.read()\n            txt1.delete(\"1.0\", tk.END)\n            txt1.insert(\"1.0\", data)\n\n    def save_file():\n        path = filedialog.asksaveasfilename(parent=win, defaultextension=\".txt\")\n        if path:\n            with open(path, \"w\", encoding=\"utf-8\") as f:\n                f.write(txt1.get(\"1.0\", \"end-1c\"))\n\n    menu = tk.Menu(win)\n    win.config(menu=menu)\n\n    filemenu = tk.Menu(menu, tearoff=0)\n    menu.add_cascade(label=\"파일\", menu=filemenu)\n    filemenu.add_command(label=\"열기\", command=open_file)\n    filemenu.add_command(label=\"저장\", command=save_file)\n\n    load_user_themes()\n\n    def save_current_theme():\n        name = simpledialog.askstring(\"테마 추가\", \"현재 색 조합의 테마 이름:\", parent=win)\n        if not name:\n            return\n        name = name.strip()\n        if not name:\n            return\n        if name in BUILTIN_THEMES:\n            messagebox.showwarning(\"테마 추가\", f\"'{name}'은(는) 기본 제공 테마 이름이라 쓸 수 없습니다.\",\n                                   parent=win)\n            return\n        THEMES[name] = {k: colors[k] for k in THEME_KEYS if colors.get(k)}\n        if not save_user_themes():\n            messagebox.showwarning(\"테마 추가\", \"파일 저장에 실패했습니다.\\n(이번 실행에서만 유지됩니다)\",\n                                   parent=win)\n        build_color_menu()\n\n    def delete_theme(name):\n        if messagebox.askyesno(\"테마 삭제\", f\"'{name}' 테마를 삭제할까요?\", parent=win):\n            THEMES.pop(name, None)\n            save_user_themes()\n            build_color_menu()\n\n    colormenu = tk.Menu(menu, tearoff=0)\n    menu.add_cascade(label=\"색상\", menu=colormenu)\n\n    def build_color_menu():\n        colormenu.delete(0, \"end\")\n        themesub = tk.Menu(colormenu, tearoff=0)\n        colormenu.add_cascade(label=\"테마 선택\", menu=themesub)\n        for name in THEMES:\n            if name in BUILTIN_THEMES:\n                themesub.add_command(label=name, command=lambda n=name: set_theme(n))\n        mine_names = [n for n in THEMES if n not in BUILTIN_THEMES]\n        if mine_names:\n            themesub.add_separator()\n            for name in mine_names:\n                themesub.add_command(label=f\"내 테마: {name}\", command=lambda n=name: set_theme(n))\n        colormenu.add_separator()\n        groupmenu = tk.Menu(colormenu, tearoff=0)\n        colormenu.add_cascade(label=\"버튼 그룹 색 직접 선택\", menu=groupmenu)\n        for g, title in GROUP_NAMES.items():\n            groupmenu.add_command(label=title, command=lambda gg=g: pick_group(gg))\n        colormenu.add_command(label=\"창 배경색 선택\",\n                              command=lambda: pick_extra(\"win\", \"창 배경색\"))\n        colormenu.add_command(label=\"기록창 배경색 선택\",\n                              command=lambda: pick_extra(\"log_bg\", \"기록창 배경색\"))\n        colormenu.add_separator()\n        colormenu.add_command(label=\"현재 색을 새 테마로 저장…\", command=save_current_theme)\n        mine = [n for n in THEMES if n not in BUILTIN_THEMES]\n        if mine:\n            delmenu = tk.Menu(colormenu, tearoff=0)\n            colormenu.add_cascade(label=\"내 테마 삭제\", menu=delmenu)\n            for n in mine:\n                delmenu.add_command(label=n, command=lambda nn=n: delete_theme(nn))\n\n    build_color_menu()\n\n    apply_colors()\n    entry1.focus_set()\n    win.mainloop()\n\n\nif __name__ == \"__main__\":\n    main()\n";
